fn char_code(s: string, i: i32) -> i32 {
  var c = substr(s, i, 1)
  return string_to_char_code(c)
}

fn string_to_char_code(c: string) -> i32 {
  // Simple mapping for common characters
  if c == "0" { return 48 }
  if c == "1" { return 49 }
  if c == "2" { return 50 }
  if c == "3" { return 51 }
  if c == "4" { return 52 }
  if c == "5" { return 53 }
  if c == "6" { return 54 }
  if c == "7" { return 55 }
  if c == "8" { return 56 }
  if c == "9" { return 57 }
  if c == "a" { return 97 }
  if c == "b" { return 98 }
  if c == "c" { return 99 }
  if c == "d" { return 100 }
  if c == "e" { return 101 }
  if c == "f" { return 102 }
  if c == "." { return 46 }
  if c == "_" { return 95 }
  if c == "-" { return 45 }
  if c == "|" { return 124 }
  return 65
}

fn abs_i32(n: i32) -> i32 {
  if n < 0 {
    return -n
  }
  return n
}

fn abs_i64(n: i64) -> i64 {
  if n < 0 {
    return -n
  }
  return n
}

fn current_time_ms() -> i64 {
  return 1000000
}

fn to_string(n: i64) -> string {
  if n == 0 {
    return "0"
  }
  var result = ""
  var v = n
  if v < 0 {
    v = -v
  }
  while v > 0 {
    var digit = v % 10
    var digit_char = "0"
    if digit == 1 { digit_char = "1" }
    if digit == 2 { digit_char = "2" }
    if digit == 3 { digit_char = "3" }
    if digit == 4 { digit_char = "4" }
    if digit == 5 { digit_char = "5" }
    if digit == 6 { digit_char = "6" }
    if digit == 7 { digit_char = "7" }
    if digit == 8 { digit_char = "8" }
    if digit == 9 { digit_char = "9" }
    result = digit_char + result
    v = v / 10
  }
  if n < 0 {
    return "-" + result
  }
  return result
}

